R=Path(__file__).resolve().parents[2];D=Path(__file__).resolve().parent;sha=lambda b:hashlib.sha256(b).hexdigest();read=lambda p:json.loads(p.read_text());canon=lambda x:json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False)
p=read(R/'data/learning-resource-policy.json');m=read(R/'audits/final-ui-policy-105-author/candidate-manifest.json');lp=R/'data/learning-resource-policy-reviews.json';ledger=read(lp)
