assert sha((R/'data/learning-resource-policy.json').read_bytes())==m['policyFileSha256']=='42e00e916ca30d5a2671dfc889b6847a8164def8f3bb7dd2d6da21d45a456779'
assert p['codeHashes']==m['codeHashes'] and all(sha((R/f).read_bytes())==h for f,h in p['codeHashes'].items())
names=['binding-checks','supplemental-producer-probes','supplemental-runtime-probes','supplemental-ui-probes','actual-source-parity','actual-source-runtime','visual-producer-probes','visual-runtime-probes','visual-ui-probes','followup-probes','real-followup-probes','independent-ui-checks'];counts={}
for name in names:
 x=read(D/(name+'.json'));assert x['failed']==0;counts[name]=x['passed']
assert 'ℹ pass 134' in (D/'shared-node-explicit.log').read_text();assert 'Ran 197 tests' in (D/'shared-python.log').read_text() and (D/'shared-python.log').read_text().rstrip().endswith('OK')
evidence={str(f.relative_to(R)):sha(f.read_bytes()) for f in sorted(D.iterdir()) if f.is_file() and f.suffix in ('.json','.js','.py','.log') and f.name!='independent-review-summary.json'}
evidence['data/reviews/L46-corrected-inputs-v2-independent-pixels.json']=sha((R/'data/reviews/L46-corrected-inputs-v2-independent-pixels.json').read_bytes())
record={'id':'recovery-independent-learning-resource-policy-v1.0.5','reviewerId':'verify_remaining_assignment_answers:independent-ui-policy-reviewer','reviewedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'resourceId':p['id'],'resourceVersion':p['version'],'resourceSha256':m['policySha256'],'decision':'verified','checks':{k:True for k in p['requiredChecks']},'findings':[],'codeHashes':p['codeHashes'],'priorExposure':'Disclosed nonblind independent code review against exact approved 1.0.4 baselines and author candidate diffs. Author tests were inspected; independent Python-generated and JavaScript software fixtures challenged exact source selection and application behavior. Actual notebook artifacts were read as inert UTF-8/JSON only, never executed. Real source metadata was also exercised under an explicitly synthetic question and software-only input approval, not promoted as factual snippet-intent approval.','closedFindings':{'UI105-R01':'Python and JavaScript now share CRLF/CR/LF physical-line splitting. Unicode line separators inside source literals remain data, preserving exact selected text.','UI105-R02':'Runtime defaults snippet revisionAuthors only when absent and rejects null/empty-string metadata, matching producer fail-closed behavior.'},'evidencePaths':list(evidence),'evidenceSha256':evidence,'limitations':['Exact code/policy acceptance only. Independent review of each actual snippet as a necessary question premise or explicit historical-output stimulus remains a separate content gate.','All 34 actual source snippets passed independent local-byte/cell/line extraction and runtime selector checks; these checks do not establish scientific correctness or question intent.','Producer malformed null revisionAuthors rejection is a raised exception before any binding, rather than a per-question diagnostic; validator rejects the malformed sidecar. This is fail-closed, not an unsafe acceptance.','Two L46 v2 question repairs are separately bound to data/reviews/L46-corrected-inputs-v2-independent-pixels.json. All other question IDs, versions, statuses and content hashes match the prior baseline; this review does not reapprove those subject-matter answers.','No browser runner, fixture CLI, notebook execution, install, Git or Library operation was invoked in this 1.0.5 review. The prior browser incident and pending actual-browser verification are preserved. Deterministic testing is not browser layout or interaction QA.','Original PDFs and PNG input gates remain intact. Offline source data and backup answer keys are readable by design; UI exam separation is not encrypted or proctored security.']}
assert not {record['reviewerId']}.intersection({p['authorId'],*p.get('revisionAuthors',[])})
assert not any(r['id']==record['id'] for r in ledger)
lp.write_text(json.dumps(ledger+[record],ensure_ascii=False,indent=2)+'\n')
summary={'recordedAt':record['reviewedAt'],'decision':'verified exact policy/code; source-content and browser gates remain separate','reviewId':record['id'],'policySha256':m['policySha256'],'policyFileSha256':m['policyFileSha256'],'policyReviewLedgerSha256':sha(lp.read_bytes()),'codeHashes':p['codeHashes'],'independentProbeCounts':counts,'actualSubtopicScopes':read(D/'actual-bank-navigation-check.json')['lazySubtopicLinks'],'sharedNodeTestsPassed':134,'sharedPythonTestsPassed':197,'runnerCLITestsExecuted':False,'browserVerified':False,'closedFindings':record['closedFindings'],'limitations':record['limitations'],'evidenceSha256':evidence}
(D/'independent-review-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
